-- Дамп структуры для таблица lkzk.sotrudniki
CREATE TABLE IF NOT EXISTS `sotrudniki` (
  `person_id` int(10) unsigned NOT NULL,
  `lecturer_uid` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chair_uid` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'для сотрудников псевдо-кафедр и для ГПХ-шников здесь стоит факультет',
  `lecturer_login` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fio` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `department_id` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `chair_id` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `podrazdelenie_id` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'мелкое подразделение (если есть)',
  `dolzhnost` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `stavka` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pkg` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pku` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `selected` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'стало не актуальным',
  `selected_chairs_ids` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'все завкафы, которые выбрали сотрудника (несколько для ГПХ и может быть псевдо-кафедр)',
  `date_remove` datetime DEFAULT NULL,
  `date_add` datetime DEFAULT NULL,
  UNIQUE KEY `person_id_chair_id` (`person_id`,`chair_id`),
  KEY `chair_id` (`chair_id`),
  KEY `selected` (`selected`),
  KEY `fio` (`fio`(191)),
  KEY `type` (`type`),
  KEY `date_remove` (`date_remove`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

